from urllib.parse import unquote_plus

def parse_query(query):
    pairs = {}
    if not query:
        return pairs
    for part in query.split("&"):
        key, _, value = part.partition("=")
        pairs[unquote_plus(key)] = unquote_plus(value)
    return pairs
